    "    return { dict: dict, keys: keys };",
    "  }",
    "  var list = [];",
    "  if (i === s.length) return { list: list };",
    "  while (i < s.length) {",
    "    var listMember = item(); if (listMember === null) return null;",
    "    list.push(listMember);",
    "    ws();",
    "    if (i === s.length) return { list: list };",
    '    if (s.charAt(i) !== ",") return null;',
    "    i += 1; ws();",
    "    if (i === s.length) return null;",
